<div class="stats"><div class="stat"><b><?= count($items) ?></b><span>Enrolments</span></div><div class="stat"><b><?= count(array_filter($items, fn($i) => $i['status'] === 'completed')) ?></b><span>Completed</span></div><div class="stat"><b><?= $quizAvg ? round($quizAvg) . '%' : '—' ?></b><span>Average best quiz score</span></div></div>
<div class="toolbar"><form class="toolbar grow" method="post" action="/admin/courses/<?= (int) $c['id'] ?>/learners" style="margin:0"><?= csrf_field() ?><input type="hidden" name="action" value="enrol"><input type="email" name="email" placeholder="Enrol a registered user by email" style="min-width:280px" required><button class="btn btn-primary btn-sm">Grant access</button></form><a class="btn btn-ghost btn-sm" href="?export=csv"><?= icon('download', 15) ?> Export CSV</a></div>
<div class="table-wrap"><table class="t"><thead><tr><th>Learner</th><th>Status</th><th>Progress</th><th>Enrolled</th><th></th></tr></thead><tbody><?php foreach ($items as $i): ?><tr><td><strong><?= e($i['name']) ?></strong><div class="muted xs"><?= e($i['email']) ?></div></td><td><?= badge($i['status'], ['active' => 'blue', 'completed' => 'green', 'pending' => 'amber', 'cancelled' => 'red'][$i['status']] ?? '') ?></td><td style="min-width:160px"><div class="progress"><i style="width:<?= (int) $i['progress'] ?>%"></i></div><span class="xs muted"><?= (int) $i['progress'] ?>%</span></td><td class="muted xs"><?= e(fmt_date($i['enrolled_at'])) ?></td>
<td><form method="post" action="/admin/courses/<?= (int) $c['id'] ?>/learners"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $i['id'] ?>"><?php if ($i['status'] === 'cancelled'): ?><button class="rowbtn" name="action" value="restore">Restore</button><?php else: ?><button class="rowbtn danger" name="action" value="revoke" data-confirm="Revoke access?">Revoke</button><?php endif; ?></form></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="center muted" style="padding:28px">No learners yet.</td></tr><?php endif; ?></tbody></table></div>
